/**
 * FUXA widget catalog -- a static index of all available community widgets.
 * In production, this is generated by a build-time script from the
 * FUXA-SVG-Widgets repository. For now, we include a representative
 * sample catalog with ~50 entries across categories.
 *
 * The catalog is a lightweight JSON structure -- actual SVG content
 * is loaded on-demand when a widget is added to the canvas.
 * This keeps the initial bundle small even with 1,450+ widgets indexed.
 *
 * Category structure mirrors the FUXA-SVG-Widgets repository layout:
 *   Process Engineering / {Pumps, Valves, Tanks, Heat Exchangers, Compressors}
 *   Electrical / {Logic, Instruments}
 *   Dynamic SVG / {Indicators, Controls, Meters}
 *   Basic / {Shapes, Flowchart}
 */

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

export interface FuxaWidgetCatalogEntry {
  /** Unique identifier matching the SVG file path in the FUXA repository */
  id: string;
  /** Human-readable display name */
  name: string;
  /** Top-level category (e.g. 'Process Engineering') */
  category: string;
  /** Optional subcategory within the main category */
  subcategory?: string;
  /**
   * Tier classification for complexity-based loading:
   * Tier 1 = standard (18 variables, 6 states) -- loads synchronously
   * Tier 2 = complex (>18 variables, animations, custom JS) -- loads lazily
   */
  tier: 1 | 2;
  /** Search tags for fuzzy matching in the browser */
  tags: string[];
  /** Number of exported configurable variables */
  variableCount: number;
  /** Brief description shown in the browser detail panel */
  description: string;
}

