/* ------------------------------------------------------------------ */
/*  Category tree helpers                                              */
/* ------------------------------------------------------------------ */

export interface CatalogCategoryNode {
  name: string;
  /** Subcategories. Empty array if the category has no subcategories. */
  children: string[];
  /** Number of widgets in this category (including all subcategories) */
  count: number;
}

/**
 * Build a category tree from the flat catalog array.
 * Used by FuxaWidgetBrowser to render the collapsible category sidebar.
 */
export function buildCategoryTree(
  catalog: FuxaWidgetCatalogEntry[],
): CatalogCategoryNode[] {
  const map = new Map<string, Set<string>>();
  const counts = new Map<string, number>();

  for (const entry of catalog) {
    if (!map.has(entry.category)) {
      map.set(entry.category, new Set());
      counts.set(entry.category, 0);
    }
    counts.set(entry.category, (counts.get(entry.category) ?? 0) + 1);

    if (entry.subcategory) {
      map.get(entry.category)!.add(entry.subcategory);
    }
  }

  return Array.from(map.entries()).map(([name, subs]) => ({
    name,
    children: Array.from(subs).sort(),
    count: counts.get(name) ?? 0,
  }));
}

/**
 * Extract all unique categories present in the catalog.
 * Used for "all categories" display in the category filter.
 */
export function getAllCategories(
  catalog: FuxaWidgetCatalogEntry[],
): string[] {
  return [...new Set(catalog.map((e) => e.category))].sort();
}
